};

/**
 * Resolve the game family for a server, same precedence as
 * lib/game-config.ts's `familyFor` (game plan first, OS template as
 * fallback) — but WITHOUT requiring a customization schema to exist, since
 * Terraria (this check's motivating incident) has no config schema yet is
 * still a game whose port must be verified. Returns null for a plain VPS or
 * an unrecognized family (never throws — an unknown family is a data/config
 * gap for the caller to log, not a health failure).
 */
export function gameFamilyForServer(server: ServerFamilyLike | null | undefined): GameFamily | null {
  if (!server) return null;
  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
  return fam && Object.prototype.hasOwnProperty.call(GAME_PORT, fam) ? (fam as GameFamily) : null;
}

/** The expected game port + transport for a server, or null (not a recognized game). */
export function gamePortForServer(server: ServerFamilyLike | null | undefined): { port: number; protocol: "tcp" | "udp" } | null {
  const fam = gameFamilyForServer(server);
  return fam ? GAME_PORT[fam] : null;
}

// ---------------------------------------------------------------------------
// Real network I/O — single-attempt probes.
// ---------------------------------------------------------------------------

/** Default per-attempt socket timeout — how long ONE connect (not the whole
 *  retry window) is allowed before giving up and trying again. */
export const TCP_ATTEMPT_TIMEOUT_MS = 5_000;

/**
 * Did the guest do any install work between two samples?
 *
 * Deliberately family-agnostic, so there is no per-image table to drift: either
 * the root filesystem grew by a real amount (a download or extract is running),
 * or the game container wrote to its log inside the sample window (world
 * generation, engine startup — work that need not move the disk much). Either
 * one counts; only both being absent means "stopped".
 */
export function installProgressed(prev: InstallSample, next: InstallSample): boolean {
  if (next.usedKb - prev.usedKb >= GAME_INSTALL_MIN_GROWTH_KB || next.logBytes > 0) return true;
  // Third signal: the container is burning CPU (asset load, world gen, shader
  // compile) even though it is silent and the disk is flat. Unknown readings
  // (-1/undefined, or a counter that went BACKWARDS because the container was
  // recreated) never count as progress.
  const a = prev.cpuUsec ?? -1;
  const b = next.cpuUsec ?? -1;
  return a >= 0 && b >= a && b - a >= GAME_INSTALL_MIN_CPU_USEC;
}

/**
 * Real TCP-or-UDP connect check (per `GAME_PORT`'s `protocol`) against the
 * server's own address at the game's actual listen port — see
 * `gamePortForServer`. Reuses the caller's already-computed `ip` (the
 * dedicated public IP, or the NAT server's private address) rather than
 * recomputing it.
 *
 * NOTE on NAT servers: only SSH gets an automatic port-forward at provision
 * time (`syncPortForwardsBestEffort`); the game's own port is forwarded only
 * if the customer adds a `PortForward` for it (lib/actions-server.ts) — a
 * separate, pre-existing product gap this task does not touch. Checking
 * against the VM's own address (not the public NAT address) still verifies
 * the thing this check exists to catch — the game process itself bound the
 * port — independent of whether that port is yet forwarded to the internet.
 */
export async function checkGamePortOpen(
  host: string,
  port: number,
  protocol: "tcp" | "udp",
  opts?: {
    timeoutMs?: number;
    intervalMs?: number;
    sleep?: (ms: number) => Promise<void>;
    /**
     * Positive confirmation that the game really is bound to the port, read
     * from inside the guest — see `procNetHasPort` and the UDP note above.
     * `true` = bound, `false` = definitely not bound, `null` = could not tell
     * (never held against the server). Required to make the UDP path mean
     * anything; harmless and still useful as a second opinion for TCP.
     */
    verifyBound?: () => Promise<boolean | null>;
    /** See retryCheck's `shouldAbort`. */
    shouldAbort?: (attempt: number) => Promise<string | null>;
  }
): Promise<RetryResult> {
  const attempt: CheckOnce =
    protocol === "tcp"
      ? () => tcpAttempt(host, port, { timeoutMs: TCP_ATTEMPT_TIMEOUT_MS, expectSshBanner: false })
      : () => udpAttempt(host, port, { timeoutMs: TCP_ATTEMPT_TIMEOUT_MS });
  const verify = opts?.verifyBound;
  const checkOnce: CheckOnce = verify
    ? async () => {
        const r = await attempt();
        if (!r.ok) return r;
        const bound = await verify();
        if (boundVerdictPasses(protocol, bound)) return r;
        return {
          ok: false,
          error:
            bound === false
              ? `the ${port}/${protocol} probe drew no refusal, but nothing inside the guest is bound to ` +
                `${port}/${protocol} — silence is not the game listening`
              : `the ${port}/udp probe drew no refusal, but the guest could not confirm anything is bound ` +
                `to ${port}/udp — for UDP that is no evidence at all, not a pass`,
        };
      }
    : attempt;
  return retryCheck(checkOnce, {
    timeoutMs: opts?.timeoutMs ?? GAME_PORT_CHECK_TIMEOUT_MS,
    intervalMs: opts?.intervalMs ?? GAME_PORT_CHECK_INTERVAL_MS,
    sleep: opts?.sleep,
    shouldAbort: opts?.shouldAbort,
  });
}

/**
 * Is a socket bound to `port` present in a `/proc/net/{udp,udp6,tcp,tcp6}`
 * table? Pure parser over the raw table text so it is unit-testable; the
 * caller concatenates the guest's own tables plus each running container's
 * (`/proc/<pid>/net/...`), because a containerised game binds the port in its
 * OWN network namespace, not the guest's.
 *
 * WHY THIS EXISTS: `udpAttempt` resolves SUCCESS on timeout — for a
 * connectionless protocol there is nothing else a generic prober can do, since
 * a healthy game server has no obligation to answer a byte of nonsense. So the
 * UDP game-port check passed on silence, and silence is exactly what a guest
 * emits while a crash-looping container is between restarts (the packet is
 * dropped rather than refused). Caught live 2026-09-07: a The Forest order was
 * marked DONE and handed over as ready while its container had restarted 118
 * times, had never started the game at all ("Missing SERVER_STEAM_ACCOUNT_TOKEN
 * … Aborting server start"), and had nothing bound to any port. That is the
 * same "the system asserting something untrue" failure this whole module was
 * written to end, just on the protocol half nobody had checked.
 *
 * `st` is only meaningful for TCP (0A = LISTEN); UDP sockets have no listen
 * state, so a bound socket is all there is to find.
 */
/**
 * Given the in-guest binding verdict (`true` bound / `false` not bound / `null`
 * could not be determined), may this attempt count as the game port being open?
 *
 * The asymmetry between the protocols is the whole point. A completed TCP
 * connect is real evidence by itself, so the in-guest read is only a second
 * opinion and "could not ask" costs nothing. A UDP probe that draws no refusal
 * is NOT evidence — `udpAttempt` reports success on silence — so without an
 * in-guest answer the attempt has established nothing, and letting "unknown"
 * pass would put the check straight back to being a no-op that any transient
 * SSH hiccup unlocks. Attempts repeat across the whole retry window, so a blip
 * costs one attempt; only a guest that stays unreachable for the entire window
 * fails here, and that guest has a real problem regardless.
 */
export function boundVerdictPasses(protocol: "tcp" | "udp", bound: boolean | null): boolean {
  if (bound === true) return true;
  if (bound === false) return false;
  return protocol === "tcp";
}

export function procNetHasPort(table: string, port: number, opts?: { tcpListeningOnly?: boolean }): boolean {
  if (!Number.isInteger(port) || port <= 0 || port > 65535) return false;
  const want = port.toString(16).toUpperCase().padStart(4, "0");
  for (const line of table.split("\n")) {
    const f = line.trim().split(/\s+/);
    // sl local_address rem_address st ...
    if (f.length < 4 || !f[1]?.includes(":")) continue;
    const local = f[1];
    const cut = local.lastIndexOf(":");
    if (local.slice(cut + 1).toUpperCase() !== want) continue;
    if (opts?.tcpListeningOnly && f[3] !== "0A") continue;
    // A socket bound to loopback INSIDE the container is bound to a network
    // nobody else is on — not the docker bridge, not the guest, certainly not a
    // player. Found live on Soulmask, whose admin port sits on 127.0.0.1:18888
    // in its namespace while `-p 18888:18888/tcp` publishes it: docker-proxy
    // accepts and the backend dial is refused. Counting that as "bound" would
    // make this check agree with a port that is provably unreachable.
    if (isLoopbackAddrHex(local.slice(0, cut))) continue;
    return true;
  }
  return false;
}

/** Is a `/proc/net` hex local address a loopback one (127.0.0.0/8, ::1, or
 *  an IPv4-mapped loopback)? Addresses are little-endian per 4-byte word, so
 *  127.0.0.1 appears as `0100007F`. */
function isLoopbackAddrHex(addr: string): boolean {
  const up = addr.toUpperCase();
  if (up.length === 8) return up.slice(6, 8) === "7F";
  if (up.length === 32) {
    if (up === "00000000000000000000000001000000") return true; // ::1
    if (up.startsWith("0000000000000000FFFF0000")) return isLoopbackAddrHex(up.slice(24)); // ::ffff:127.x.x.x
    return false;
  }
  return false;
}

