export async function probeGameRuntime(
  server: RuntimeServer,
  opts?: { external?: boolean; now?: Date }
): Promise<RuntimeProbeResult | null> {
  const family = familyOf(server);
  if (!family) return null;
  const spec = controlSpec(family);
  const game = GAME_PORT[family];
  const intent = (server.gameRuntime?.intent as RunIntent | null) ?? null;
  const now = opts?.now ?? new Date();
  if (!spec || !game) return null;

  if (SANDBOX) {
    // No VM exists. Report what the owner last asked for and say it is simulated.
    const state: GameRuntimeState = intent === "stopped" ? "stopped" : "online";
    return {
      family,
      probe: { ...emptyProbe(), ok: true, unit: `${spec.serviceHints[0]}.service`, service: intent === "stopped" ? "inactive" : "active" },
      portBound: intent === "stopped" ? false : true,
      externalOk: null,
      externalTarget: null,
      state,
      error: "sandbox: simulated, no VM contacted",
    };
  }
  if (server.status !== "RUNNING") {
    return { family, probe: emptyProbe(), portBound: null, externalOk: null, externalTarget: null, state: "unknown", error: "VM is not running" };
  }

  let probe = emptyProbe();
  let error: string | null = null;
  try {
    const script = runtimeProbeScript({ hints: spec.serviceHints, family, protocol: game.protocol });
    const r = await withServerSsh(server as SftpServer, (conn) => exec(conn, script, QUICK_TIMEOUT_MS));
    probe = parseRuntimeProbe(r.stdout);
    if (!probe.ok) error = "probe did not complete";
  } catch (e) {
    error = String((e as Error)?.message ?? e).slice(0, 300);
  }

  let portBound: boolean | null = null;
  if (probe.ok) {
    if (probe.netTable !== null) portBound = procNetHasPort(probe.netTable, game.port, { tcpListeningOnly: game.protocol === "tcp" });
    else if (probe.netAbsent) portBound = false;
  }

  let externalOk: boolean | null = null;
  let externalTarget: string | null = null;
  // Only worth asking the outside world when the inside says the game is listening.
  if (opts?.external !== false && portBound === true) {
    const ext = await externalTcpCheck(server, game).catch(() => ({ ok: null, target: null }));
    externalOk = ext.ok;
    externalTarget = ext.target;
  }

  const state = classifyRuntime({ probe, portBound, externalOk, intent, now });
  return { family, probe, portBound, externalOk, externalTarget, state, error };
}

