// is hibernating", never loaded its map, answered no A2S query at all - and the
// TCP check at 27015 passed every time, so the order was handed over as ready.
// For families listed here the provision gate also asks the game the question a
// player's server browser asks (A2S_INFO) and requires a Source-protocol answer.

/** Families whose provisioning must also see an A2S answer, not just an open port. */
export const A2S_READINESS_FAMILIES: ReadonlySet<string> = new Set(["l4d2"]);

export type A2sReplyKind = "answering" | "rejected" | "silent";

/**
 * Classify the first bytes (hex, any spacing/case) of the reply to an A2S_INFO request.
 *   ffffffff49 'I'  info          -> answering (map loaded, serving)
 *   ffffffff41 'A'  S2C_CHALLENGE -> answering (the engine only issues one for a running map)
 *   ffffffff6c 'l'  reject        -> rejected  ("Banned by server" - engine up but no map/lobby)
 *   anything else / nothing       -> silent
 */
export function classifyA2sReply(hex: string): A2sReplyKind {
  const h = (hex ?? "").replace(/[^0-9a-fA-F]/g, "").toLowerCase();
  if (h.startsWith("ffffffff49") || h.startsWith("ffffffff41")) return "answering";
  if (h.startsWith("ffffffff6c")) return "rejected";
  return "silent";
}

/**
 * Bash (no python/nc needed) that sends one A2S_INFO to `<guest's own primary IP>:port`
 * and prints `NXA2S:<hex of first 5 reply bytes>` (empty = silence). The guest's own
 * address is used on purpose: srcds ignores queries from 127.0.0.1, and a datagram to
 * the guest's address still travels the docker UDP publish path a player's would.
 * `host` is overridable only for tests.
 */
export function a2sGuestProbeScript(port: number, host?: string): string {
  if (!Number.isInteger(port) || port <= 0 || port > 65535) throw new Error(`bad port ${port}`);
  if (host !== undefined && !/^[0-9.]+$/.test(host)) throw new Error(`bad host ${host}`);
  const target = host ?? "$(hostname -I | awk '{print $1}')";
  return (
    `h=${target}; ` +
    `r=$(timeout 4 bash -c 'exec 3<>/dev/udp/'"$h"'/${port}; printf "\\xff\\xff\\xff\\xffTSource Engine Query\\x00" >&3; head -c 5 <&3' 2>/dev/null | od -An -tx1 | tr -d ' \\n'); ` +
    `echo "NXA2S:$r"`
  );
}

/** Parse the output of `a2sGuestProbeScript`; null when the marker is missing (could not ask). */
export function parseA2sGuestProbe(stdout: string): A2sReplyKind | null {
  const m = /NXA2S:([0-9a-fA-F]*)/.exec(stdout ?? "");
  return m ? classifyA2sReply(m[1]) : null;
}

/**
 * Wait for the game to answer A2S. `ask` runs one probe and returns its stdout (injected so the
 * worker passes an SSH exec and tests pass a fake). "could not ask" (null/throw) never counts as
 * an answer but is reported distinctly from a real silence/reject, so the error is honest.
 */
export async function checkA2sAnswers(
  port: number,
  ask: (script: string) => Promise<string | null>,
  opts?: { timeoutMs?: number; intervalMs?: number; sleep?: (ms: number) => Promise<void>; host?: string; shouldAbort?: (attempt: number) => Promise<string | null> }
): Promise<RetryResult> {
  const script = a2sGuestProbeScript(port, opts?.host);
  const checkOnce: CheckOnce = async () => {
    let out: string | null = null;
    try {
      out = await ask(script);
    } catch {
      out = null;
    }
    const kind = out === null ? null : parseA2sGuestProbe(out);
    if (kind === "answering") return { ok: true, detail: "A2S_INFO answered" };
    if (kind === "rejected") {
      return { ok: false, error: `the game port is open but the server rejects queries ("Banned by server") - the engine is up but no map has loaded` };
    }
    if (kind === "silent") {
      return { ok: false, error: `the game port is open but the server never answers A2S_INFO - the process is up without a running map (hibernating at startup)` };
    }
    return { ok: false, error: "could not ask the guest to query the game (SSH/probe unavailable)" };
  };
  return retryCheck(checkOnce, {
    timeoutMs: opts?.timeoutMs ?? A2S_READY_TIMEOUT_MS,
    intervalMs: opts?.intervalMs ?? A2S_READY_INTERVAL_MS,
    sleep: opts?.sleep,
    shouldAbort: opts?.shouldAbort,
  });
}

/** Map load + first Steam/hibernation settle: L4D2 measured ~40-60 s from container start. */
export const A2S_READY_TIMEOUT_MS = 240_000;
export const A2S_READY_INTERVAL_MS = 8_000;
