import { test } from "node:test";
import assert from "node:assert/strict";
import dgram from "node:dgram";
import { execFile } from "node:child_process";
import { readFileSync } from "node:fs";
import {
  applyL4d2CfgSeed,
  buildGameSetupScript,
  dockerContainerNameFrom,
  dockerHostMountsFrom,
} from "../worker/game-variant.ts";
import {
  A2S_READINESS_FAMILIES,
  a2sGuestProbeScript,
  checkA2sAnswers,
  classifyA2sReply,
  parseA2sGuestProbe,
} from "../worker/provision-health.ts";

// The l4d2 setup script exactly as it is in the production OsTemplate row today (pre-fix).
const PROD_SCRIPT =
  "curl -fsSL https://get.docker.com | sh && mkdir -p /opt/l4d2/addons /opt/l4d2/cfg && chown -R 1000:1000 /opt/l4d2 && docker run -d --name l4d2 --restart unless-stopped -p 27015:27015 -p 27015:27015/udp -e HOSTNAME='Nxeon L4D2' -e RCON_PASSWORD='changeme12' -e PORT='27015' -e DEFAULT_MODE='coop' -v /opt/l4d2/addons:/addons -v /opt/l4d2/cfg:/cfg left4devops/l4d2:latest";

test("the seed file's l4d2 script already carries the cfg seed, and the transform is idempotent on it", () => {
  const seed = readFileSync(new URL("../prisma/seed-wave4-games.ts", import.meta.url), "utf8");
  assert.match(seed, /--entrypoint \/bin\/cp left4devops\/l4d2:latest -an \/cfg\/\. \/seed\//);
  const once = applyL4d2CfgSeed(PROD_SCRIPT, "l4d2");
  assert.equal(applyL4d2CfgSeed(once, "l4d2"), once, "second application changes nothing");
});

test("applyL4d2CfgSeed copies the image's /cfg into the bind mount BEFORE the real container, as uid 1000, no-clobber", () => {
  const out = applyL4d2CfgSeed(PROD_SCRIPT, "l4d2");
  const seedAt = out.indexOf("--entrypoint /bin/cp");
  const runAt = out.indexOf("docker run -d");
  assert.ok(seedAt > 0 && seedAt < runAt, "seed runs first");
  assert.match(out, /docker run --rm --user 1000:1000 -v \/opt\/l4d2\/cfg:\/seed --entrypoint \/bin\/cp left4devops\/l4d2:latest -an \/cfg\/\. \/seed\/ && docker run -d/);
  // schema fields that were silently no-ops (applyGameConfigEnv only rewrites an env already in the script)
  assert.match(out, /-e DEFAULT_MAP='c1m1_hotel'/);
  assert.match(out, /-e GAME_TYPES=''/);
  // the seed must come after the chown so uid 1000 can write the mount
  assert.ok(out.indexOf("chown -R 1000:1000 /opt/l4d2") < seedAt);
});

test("applyL4d2CfgSeed leaves every other family (and a customised DEFAULT_MAP) alone", () => {
  assert.equal(applyL4d2CfgSeed(PROD_SCRIPT, "tf2"), PROD_SCRIPT);
  assert.equal(applyL4d2CfgSeed(PROD_SCRIPT, null), PROD_SCRIPT);
  const custom = PROD_SCRIPT.replace("-e PORT='27015'", "-e PORT='27015' -e DEFAULT_MAP='c2m1_highway'");
  const out = applyL4d2CfgSeed(custom, "l4d2");
  assert.equal((out.match(/DEFAULT_MAP=/g) ?? []).length, 1);
  assert.match(out, /DEFAULT_MAP='c2m1_highway'/);
});

test("buildGameSetupScript: the seed survives the systemd/docker-create wrap; container name and wipe mounts are unchanged", () => {
  const built = buildGameSetupScript({ osTemplate: { setupScript: PROD_SCRIPT, family: "l4d2" }, gameVariant: "coop", gameConfig: { DEFAULT_MAP: "c8m1_apartment", HOSTNAME: "Lat L4D2" } })!;
  assert.match(built, /--entrypoint \/bin\/cp left4devops\/l4d2:latest -an \/cfg\/\. \/seed\//);
  assert.match(built, /docker create --name l4d2 /);
  assert.match(built, /DEFAULT_MAP='c8m1_apartment'/, "customer's map choice now actually reaches the container");
  assert.match(built, /HOSTNAME='Lat L4D2'/);
  const fixed = applyL4d2CfgSeed(PROD_SCRIPT, "l4d2");
  assert.equal(dockerContainerNameFrom(fixed), "l4d2");
  assert.deepEqual(dockerHostMountsFrom(fixed), dockerHostMountsFrom(PROD_SCRIPT), "reinstall wipes the same host dirs as before");
});

test("classifyA2sReply: info/challenge answer, reject 'l' is the Banned-by-server shape, anything else is silence", () => {
  assert.equal(classifyA2sReply("ff ff ff ff 41"), "answering");
  assert.equal(classifyA2sReply("FFFFFFFF49"), "answering");
  assert.equal(classifyA2sReply("ffffffff6c"), "rejected");
  assert.equal(classifyA2sReply(""), "silent");
  assert.equal(classifyA2sReply("0000000000"), "silent");
});

test("a TCP-open-but-silent Source server is NOT ready; one that answers after a few tries is", async () => {
  const sleeps: number[] = [];
  const sleep = async (ms: number) => void sleeps.push(ms);
  // silent forever (the reproduced bug: hibernating, no map, RCON TCP open)
  const silent = await checkA2sAnswers(27015, async () => "NXA2S:", { timeoutMs: 40_000, intervalMs: 8_000, sleep });
  assert.equal(silent.ok, false);
  assert.match(!silent.ok ? silent.error : "", /never answers A2S_INFO|hibernating/);
  // 'Banned by server'
  const banned = await checkA2sAnswers(27015, async () => "NXA2S:ffffffff6c", { timeoutMs: 16_000, intervalMs: 8_000, sleep });
  assert.equal(banned.ok, false);
  assert.match(!banned.ok ? banned.error : "", /Banned by server/);
  // could not ask is reported as such, never as an answer
  const unknown = await checkA2sAnswers(27015, async () => { throw new Error("ssh down"); }, { timeoutMs: 16_000, intervalMs: 8_000, sleep });
  assert.equal(unknown.ok, false);
  assert.match(!unknown.ok ? unknown.error : "", /could not ask/);
  // map loads on the 3rd attempt
  let n = 0;
  const late = await checkA2sAnswers(27015, async () => (++n < 3 ? "NXA2S:" : "NXA2S:ffffffff41"), { timeoutMs: 80_000, intervalMs: 8_000, sleep });
  assert.equal(late.ok, true);
  assert.equal(late.attempts, 3);
});

test("l4d2 is gated on the A2S answer; the guest probe script validates its inputs", () => {
  assert.ok(A2S_READINESS_FAMILIES.has("l4d2"));
  assert.throws(() => a2sGuestProbeScript(0));
  assert.throws(() => a2sGuestProbeScript(27015, "1.2.3.4; rm -rf /"));
  assert.equal(parseA2sGuestProbe("garbage"), null);
  assert.equal(parseA2sGuestProbe("NXA2S:ffffffff41\n"), "answering");
});

/* The REAL guest script, run through real bash against real UDP sockets. */
function serve(reply: Buffer | null): Promise<{ port: number; close: () => void }> {
  return new Promise((resolve) => {
    const s = dgram.createSocket("udp4");
    s.on("message", (_m, r) => {
      if (reply) s.send(reply, r.port, r.address);
    });
    s.bind(0, "127.0.0.1", () => resolve({ port: s.address().port, close: () => s.close() }));
  });
}
function runScript(script: string): Promise<string> {
  return new Promise((resolve, reject) =>
    execFile("bash", ["-c", script], { timeout: 15_000 }, (e, out) => (e ? reject(e) : resolve(out)))
  );
}

test("guest probe script against a real UDP server: challenge => answering, reject => rejected, silence => silent", async () => {
  const cases: Array<[Buffer | null, string]> = [
    [Buffer.from([0xff, 0xff, 0xff, 0xff, 0x41, 1, 2, 3, 4]), "answering"],
    [Buffer.concat([Buffer.from([0xff, 0xff, 0xff, 0xff, 0x6c]), Buffer.from("Banned by server\0")]), "rejected"],
    [null, "silent"],
  ];
  for (const [reply, want] of cases) {
    const srv = await serve(reply);
    try {
      const out = await runScript(a2sGuestProbeScript(srv.port, "127.0.0.1"));
      assert.equal(parseA2sGuestProbe(out), want, `reply ${reply?.toString("hex") ?? "none"} -> ${out}`);
    } finally {
      srv.close();
    }
  }
});

